'use strict';

const fs = require('fs');
const input = fs.readFileSync(0);

let pos = 0;
function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let value = 0;
  while (pos < input.length && input[pos] > 32) {
    value = value * 10 + input[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const stateCount = 2 * M;

const head = new Int32Array(2 * N + 1);
head.fill(-1);

const from = new Int32Array(stateCount);
const next = new Int32Array(stateCount);
const dp = new Int32Array(stateCount);
let id = 0;

function addState(a, b) {
  from[id] = a;
  const sum = a + b;
  next[id] = head[sum];
  head[sum] = id;
  id++;
}

for (let i = 0; i < M; i++) {
  const a = nextInt() - 1;
  const b = nextInt() - 1;
  addState(a, b);
  addState(b, a);
}

const bestFrom = new Int32Array(N);
const answer = new Int32Array(N);
answer.fill(1);

for (let sum = 2 * N - 2; sum >= 0; sum--) {
  let state = head[sum];

  // Compute the whole sum group before updating bestFrom, since
  // transitions must strictly increase the sum.
  for (let cur = state; cur !== -1; cur = next[cur]) {
    const a = from[cur];
    const continuation = bestFrom[sum - a];
    const length = continuation === 0 ? 2 : continuation + 1;
    dp[cur] = length;
    if (length > answer[a]) answer[a] = length;
  }

  for (let cur = state; cur !== -1; cur = next[cur]) {
    const a = from[cur];
    if (dp[cur] > bestFrom[a]) bestFrom[a] = dp[cur];
  }
}

let output = '';
for (let i = 0; i < N; i++) {
  if (i > 0) output += ' ';
  output += answer[i];
}
process.stdout.write(output + '\n');
